// Stage 5.1.3 — Transform + Validate
const REQUIRED = {
  projects: ['id', 'name', 'status'],
  tasks: ['id', 'projectId', 'title', 'status'],
  milestones: ['id', 'projectId', 'name'],
  issues: ['id', 'projectId', 'title', 'status'],
  bankGuarantees: ['id', 'ref', 'expiryDate', 'amount'],
  invoices: ['id', 'projectId', 'amount'],
  dlpRecords: ['id', 'projectId', 'dlpExpiry'],
  retentionRecords: ['id', 'projectId', 'retentionHeld'],
  members: ['id', 'name', 'role'],
  companies: ['id', 'name']
};

const rows = $input.all();
const valid = [];
const errors = [];

for (const row of rows) {
  const d = row.json;
  const col = d._collection || d.collection || '';
  if (!col || !REQUIRED[col]) {
    errors.push({ json: { error: 'Unknown collection', row: d, _collection: '_errors' } });
    continue;
  }
  const missing = REQUIRED[col].filter(f => !d[f] && d[f] !== 0);
  if (missing.length > 0) {
    errors.push({ json: { error: 'Missing required fields: ' + missing.join(', '), row: d, _collection: '_errors' } });
    continue;
  }
  valid.push({ json: d });
}

if (valid.length === 0 && errors.length > 0) {
  return errors;
}
return [...valid, ...errors];

// Convert plain JSON to Firestore REST API format
const data = $input.first().json;
const collection = data._collection || data.collection;
const docId = data.id;

// Remove internal fields
const clean = { ...data };
delete clean._collection;
delete clean.collection;

// Convert to Firestore fields format
function toFirestoreValue(val) {
  if (val === null || val === undefined) return { nullValue: null };
  if (typeof val === 'string') return { stringValue: val };
  if (typeof val === 'number') {
    return Number.isInteger(val) ? { integerValue: String(val) } : { doubleValue: val };
  }
  if (typeof val === 'boolean') return { booleanValue: val };
  if (Array.isArray(val)) {
    return { arrayValue: { values: val.map(v => toFirestoreValue(v)) } };
  }
  if (typeof val === 'object') {
    const fields = {};
    for (const [k, v] of Object.entries(val)) {
      fields[k] = toFirestoreValue(v);
    }
    return { mapValue: { fields } };
  }
  return { stringValue: String(val) };
}

const fields = {};
for (const [key, val] of Object.entries(clean)) {
  fields[key] = toFirestoreValue(val);
}

return [{
  json: {
    _firestoreCollection: collection,
    _firestoreDocId: docId,
    _firestoreBody: { fields },
    _updateMask: Object.keys(clean).map(k => 'updateMask.fieldPaths=' + k).join('&')
  }
}];

// Prepare sync audit log for Firestore
const data = $input.first().json;
const docId = 'sync-' + Date.now();

function toFirestoreValue(val) {
  if (val === null || val === undefined) return { nullValue: null };
  if (typeof val === 'string') return { stringValue: val };
  if (typeof val === 'number') return Number.isInteger(val) ? { integerValue: String(val) } : { doubleValue: val };
  if (typeof val === 'boolean') return { booleanValue: val };
  if (Array.isArray(val)) return { arrayValue: { values: val.map(v => toFirestoreValue(v)) } };
  if (typeof val === 'object') {
    const fields = {};
    for (const [k, v] of Object.entries(val)) fields[k] = toFirestoreValue(v);
    return { mapValue: { fields } };
  }
  return { stringValue: String(val) };
}

const fields = {};
for (const [key, val] of Object.entries(data)) fields[key] = toFirestoreValue(val);
fields.timestamp = toFirestoreValue(new Date().toISOString());

return [{ json: { _firestoreCollection: 'syncLogs', _firestoreDocId: docId, _firestoreBody: { fields } } }];
